<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { ApiError, describeError, request, workspacePath, formatDate, type Workspace } from './api'
import { discoveryProviders, type DiscoverySource, type DiscoveryRule, type DiscoveryRun } from './discovery'
const props=defineProps<{workspace:Workspace}>(); const emit=defineEmits<{sessionExpired:[]}>()
const ruleStatusLabels:Record<string,string>={draft:'草稿',published:'已发布',retired:'已停用'}
const base=workspacePath(props.workspace.slug)+'/discovery';const sources=ref<DiscoverySource[]>([]);const rules=ref<DiscoveryRule[]>([]);const runs=ref<DiscoveryRun[]>([]);const error=ref('');const notice=ref('');const busy=ref(false);const token=ref('');const editing=ref<number|undefined>();const scopeText=ref('');const selectedSource=ref('');const owner=computed(()=>props.workspace.role==='owner');const canEdit=computed(()=>owner.value||props.workspace.role==='operator');let timer:ReturnType<typeof setInterval>|undefined
const blank=()=>({source:'',provider:'mysql',system:'mysql',database:'',scopes:[] as string[],service:'',intervalMinutes:15,enabled:true,revision:0});const form=ref(blank());const rule=ref<DiscoveryRule>({key:'',version:1,name:'',kind:'keyword',target:'metadata',category:'business',expression:'',dictionary:[],status:'draft'});const dictionary=ref('');const ruleForm=ref(false);const sourceForm=ref(false)
function failed(e:unknown){if(e instanceof ApiError&&e.status===401){emit('sessionExpired');return}error.value=describeError(e)}
async function load(){try{const [a,b]=await Promise.all([request<{items:DiscoverySource[]}>(base+'/sources'),request<{items:DiscoveryRule[]}>(base+'/rules')]);sources.value=a.items;rules.value=b.items}catch(e){failed(e)}}
function edit(s?:DiscoverySource){form.value=s?{source:s.source,provider:s.provider,system:s.system,database:s.database,scopes:[...s.scopes],service:s.service,intervalMinutes:s.intervalMinutes,enabled:s.enabled,revision:s.revision}:blank();editing.value=s?.id;scopeText.value=s?.scopes.join(',')||'';sourceForm.value=true;token.value=''}
async function save(){busy.value=true;error.value='';try{form.value.scopes=scopeText.value.split(',').map(v=>v.trim()).filter(Boolean);if(form.value.provider!=='openmetadata')form.value.system=form.value.provider;const result=await request<{source:DiscoverySource;token:string}>(base+'/sources'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:JSON.stringify(form.value)});token.value=result.token;sourceForm.value=false;notice.value='任务已保存。客户侧采集器在线时会领取计划和立即任务。';await load()}catch(e){failed(e)}finally{busy.value=false}}
async function queue(s:DiscoverySource,mode:string){error.value='';try{await request(base+'/sources/'+s.id+'/run',{method:'POST',body:JSON.stringify({revision:s.revision,mode})});notice.value=mode==='test'?'已排队测试连接。请保持客户侧采集器在线，并查看运行记录。':'已排队立即采集。';await load();await history(s)}catch(e){failed(e)}}
async function history(s:DiscoverySource){try{selectedSource.value=s.source;const r=await request<{items:DiscoveryRun[]}>(base+'/sources/'+s.id+'/runs');runs.value=r.items}catch(e){failed(e)}}
async function rotate(s:DiscoverySource){try{const r=await request<{token:string}>(base+'/sources/'+s.id+'/token',{method:'POST',body:JSON.stringify({revision:s.revision})});token.value=r.token;notice.value='旧令牌已失效，请更新客户侧采集器。';await load()}catch(e){failed(e)}}
async function saveRule(){busy.value=true;try{rule.value.dictionary=dictionary.value.split('\n').map(v=>v.trim()).filter(Boolean);await request(base+'/rules',{method:'POST',body:JSON.stringify(rule.value)});ruleForm.value=false;notice.value='识别规则版本已保存。发布后由客户侧采集器领取。';await load()}catch(e){failed(e)}finally{busy.value=false}}
async function publish(r:DiscoveryRule){try{await request(base+'/rules/publish',{method:'POST',body:JSON.stringify({key:r.key,version:r.version})});await load()}catch(e){failed(e)}}
function newVersion(r?:DiscoveryRule){rule.value=r?{...r,version:Math.max(...rules.value.filter(v=>v.key===r.key).map(v=>v.version))+1,status:'draft',dictionary:[...r.dictionary]}:{key:'',version:1,name:'',kind:'keyword',target:'metadata',category:'business',expression:'',dictionary:[],status:'draft'};dictionary.value=rule.value.dictionary.join('\n');ruleForm.value=true}
onMounted(()=>{void load();timer=setInterval(async()=>{await load();const s=sources.value.find(v=>v.source===selectedSource.value);if(s)await history(s)},15000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
<section class="discovery-page">
 <header class="page-header"><div><p class="eyebrow">DDLC · 数据发现</p><h1>多源发现与识别规则</h1><p>采集库表、字段、注释和来源允许的权限与血缘；原始样本保留在客户侧。</p></div><button v-if="owner" class="button primary" @click="edit()">新增采集任务</button></header>
 <p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <aside v-if="token" class="discovery-card"><h2>客户侧任务令牌 · 仅此时显示</h2><input :value="token" readonly aria-label="客户侧任务令牌"><p>将令牌放入客户环境的 SCARLET_DISCOVERY_TOKEN。平台地址设为 SCARLET_URL，数据库连接设为 SCARLET_DISCOVERY_DSN；OpenMetadata 使用 SCARLET_OPENMETADATA_URL 和 SCARLET_OPENMETADATA_TOKEN。</p><code>go run ./cmd/discovery-agent -poll 15s</code><p>本地回环开发增加 -allow-insecure-loopback。凭据请使用环境变量或受控的服务配置。</p><button class="button" @click="token=''">已保存，关闭</button></aside>
 <form v-if="sourceForm" class="discovery-card discovery-form" @submit.prevent="save"><h2>{{editing?'编辑':'新增'}}客户侧采集任务</h2><label>来源名称<input v-model="form.source" required maxlength="80"></label><label>接入方式<select v-model="form.provider" :disabled="Boolean(editing)"><option v-for="(label,key) in discoveryProviders" :key="key" :value="key">{{label}}</option></select></label><label>数据库名称<input v-model="form.database" required maxlength="128"></label><label>授权范围（逗号分隔）<input v-model="scopeText" placeholder="PG/OM: schema；Mongo: collection；MySQL留空"></label><template v-if="form.provider==='openmetadata'"><label>OpenMetadata 服务名<input v-model="form.service" required></label><label>源数据库类型<select v-model="form.system"><option v-for="s in ['postgresql','mysql','mariadb','mongodb','mssql','oracle','db2','hive','clickhouse','snowflake','bigquery','redshift','trino','presto','spark','databricks']" :key="s">{{s}}</option></select></label></template><label>周期（分钟）<input v-model.number="form.intervalMinutes" type="number" min="1" max="1440" required></label><label><input v-model="form.enabled" type="checkbox">启用任务</label><p>配置修订会使旧批次失效，下一次成功采集后恢复精确库表关联。数据库密码仅配置于客户侧。</p><div><button class="button primary" :disabled="busy">保存任务</button> <button class="button" type="button" @click="sourceForm=false">取消</button></div></form>
 <div class="table-scroll"><table><thead><tr><th>来源 / 数据库</th><th>接入方式</th><th>采集状态</th><th>计划</th><th>操作</th></tr></thead><tbody><tr v-for="s in sources" :key="s.id"><td><strong>{{s.source}}</strong><br>{{s.database}} · v{{s.revision}}</td><td>{{discoveryProviders[s.provider]}}<br><small>{{s.system}} · {{s.scopes.join(', ')||'数据库内授权目录'}}</small></td><td>{{!s.enabled?'已暂停':s.running?'采集中':s.queued?'等待客户采集器':s.latestRun?.status==='success'?'已采集':s.latestRun?.status==='error'?'采集失败':'尚未采集'}}<br><small v-if="s.latestRun">{{formatDate(s.latestRun.observedAt)}}</small></td><td>每 {{s.intervalMinutes}} 分钟<br>{{formatDate(s.nextRunAt)}}</td><td><button class="button" @click="history(s)">运行记录</button><template v-if="owner"> <button class="button" @click="edit(s)">配置</button> <button class="button" @click="rotate(s)">更换令牌</button> <button class="button" :disabled="s.running||!s.enabled" @click="queue(s,'test')">测试连接</button> <button class="button" :disabled="s.running||!s.enabled" @click="queue(s,'collect')">立即采集</button></template></td></tr><tr v-if="!sources.length"><td colspan="5">尚无多源采集任务。现有 PostgreSQL 托管任务可继续在自动采集中配置。</td></tr></tbody></table></div>
 <section v-if="selectedSource" class="discovery-card"><h2>{{selectedSource}} · 最近30次运行</h2><p v-if="!runs.length">尚无结果。排队任务需要客户侧采集器在线。</p><article v-for="r in runs" :key="r.id"><strong>{{r.mode==='test'?'连接测试':'目录采集'}} · {{r.status==='success'?'成功':'失败'}}</strong> · {{formatDate(r.observedAt)}} · 配置v{{r.revision}}<p v-if="r.status==='error'">采集失败，请在客户侧检查连接、TLS、账号权限与范围。</p><p v-else>元数据 {{r.coverage.metadata}} · 内容 {{r.coverage.content}} · 权限 {{r.coverage.permissions}} · 血缘 {{r.coverage.lineage}}</p><details><summary>范围与限制</summary><pre>{{JSON.stringify(r.coverage,null,2)}}</pre></details></article></section>
 <header class="page-header"><div><h2>自定义识别规则</h2><p>关键词、RE2正则与精确词典；发布版本固定到每次命中证据，命中为候选，人工确认优先。</p></div><button v-if="canEdit" class="button" @click="newVersion()">新增规则</button></header>
 <form v-if="ruleForm" class="discovery-card discovery-form" @submit.prevent="saveRule"><label>规则标识<input v-model="rule.key" required maxlength="80"></label><label>规则名称<input v-model="rule.name" required maxlength="160"></label><label>版本<input v-model.number="rule.version" type="number" min="1" required></label><label>类型<select v-model="rule.kind"><option value="keyword">关键词（逗号分隔）</option><option value="regexp">RE2正则</option><option value="dictionary">精确词典</option></select></label><label>识别范围<select v-model="rule.target"><option value="metadata">字段名 / 注释 / 类型</option><option value="content">客户侧受限内容样本</option></select></label><label>候选类别<input v-model="rule.category" required maxlength="80"></label><label v-if="rule.kind!=='dictionary'">表达式<textarea v-model="rule.expression" required maxlength="2048"></textarea></label><label v-else>词典（每行一项，最多1000项）<textarea v-model="dictionary" required></textarea></label><label>保存状态<select v-model="rule.status"><option value="draft">草稿</option><option value="published">发布</option></select></label><div><button class="button primary" :disabled="busy">保存版本</button> <button type="button" class="button" @click="ruleForm=false">取消</button></div></form>
 <div class="table-scroll"><table><thead><tr><th>规则</th><th>方法 / 范围</th><th>候选类别</th><th>版本 / 状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rules" :key="r.key+':'+r.version"><td>{{r.name}}<br><small>{{r.key}}</small></td><td>{{r.kind}} · {{r.target}}</td><td>{{r.category}}</td><td>v{{r.version}} · {{r.status?ruleStatusLabels[r.status]||'状态待确认':'内置'}}</td><td><template v-if="canEdit&&!r.key.startsWith('builtin.')"><button class="button" @click="newVersion(r)">新版本</button> <button v-if="r.status==='draft'" class="button" @click="publish(r)">发布</button></template></td></tr></tbody></table></div>
</section>
</template>
<style scoped>.discovery-page{display:grid;gap:1.2rem}.discovery-card{border:1px solid var(--border,#ddd);border-radius:12px;padding:1.2rem;background:var(--surface,#fff)}.discovery-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1rem}.discovery-form label{display:grid;gap:.4rem}.discovery-form h2,.discovery-form p,.discovery-form>div{grid-column:1/-1}input,select,textarea{max-width:100%;padding:.65rem;border:1px solid #ccd3d1;border-radius:6px}input[type=checkbox]{width:auto}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:.8rem;text-align:left;border-bottom:1px solid #e2e7e4}td .button{margin:.2rem}pre{white-space:pre-wrap;overflow-wrap:anywhere}article{padding:.6rem 0;border-bottom:1px solid #eee}</style>
